CREATE OR REPLACE FUNCTION public.admin_delete_subtest(p_subtest_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT check_is_admin() THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;

  DELETE FROM official_subtests WHERE id = p_subtest_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_delete_test(p_test_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT check_is_admin() THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;

  DELETE FROM official_tests WHERE id = p_test_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_merge_tests(p_source_ids text[], p_target_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_source_id text;
  v_source_sub RECORD;
  v_target_sub_id text;
  v_merged_tests int := 0;
  v_moved_subtests int := 0;
  v_migrated_norms int := 0;
  v_updated_sessions int := 0;
  v_target_name text;
  v_row_cnt int;
BEGIN
  IF NOT check_is_admin() THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  SELECT t.name INTO v_target_name FROM official_tests t WHERE t.id = p_target_id;
  IF v_target_name IS NULL THEN
    RAISE EXCEPTION 'Target test not found: %', p_target_id;
  END IF;

  FOREACH v_source_id IN ARRAY p_source_ids
  LOOP
    IF v_source_id = p_target_id THEN CONTINUE; END IF;

    FOR v_source_sub IN
      SELECT s.id, s.name, s.unit, s.score_type, s.computation_mode, s.organization_id
      FROM official_subtests s WHERE s.test_id = v_source_id
    LOOP
      SELECT s.id INTO v_target_sub_id
      FROM official_subtests s
      WHERE s.test_id = p_target_id
        AND norm_subtest_name(s.name) = norm_subtest_name(v_source_sub.name)
        AND s.organization_id IS NOT DISTINCT FROM v_source_sub.organization_id
      LIMIT 1;

      IF v_target_sub_id IS NOT NULL THEN
        -- Migrate norms with full 9-field dedup
        WITH inserted AS (
          INSERT INTO official_norms (subtest_id, organization_id, age_min_months, age_max_months, gender, raw_min, raw_max, mean, sd, standard_score, percentile)
          SELECT v_target_sub_id, n.organization_id, n.age_min_months, n.age_max_months, n.gender,
                 n.raw_min, n.raw_max, n.mean, n.sd, n.standard_score, n.percentile
          FROM official_norms n
          WHERE n.subtest_id = v_source_sub.id
            AND NOT EXISTS (
              SELECT 1 FROM official_norms ex
              WHERE ex.subtest_id = v_target_sub_id
                AND ex.age_min_months IS NOT DISTINCT FROM n.age_min_months
                AND ex.age_max_months IS NOT DISTINCT FROM n.age_max_months
                AND ex.gender IS NOT DISTINCT FROM n.gender
                AND ex.raw_min IS NOT DISTINCT FROM n.raw_min
                AND ex.raw_max IS NOT DISTINCT FROM n.raw_max
                AND ex.mean IS NOT DISTINCT FROM n.mean
                AND ex.sd IS NOT DISTINCT FROM n.sd
                AND ex.standard_score IS NOT DISTINCT FROM n.standard_score
                AND ex.percentile IS NOT DISTINCT FROM n.percentile
            )
          RETURNING id
        )
        SELECT count(*) INTO v_row_cnt FROM inserted;
        v_migrated_norms := v_migrated_norms + v_row_cnt;

        -- Remap contribution_insights
        UPDATE contribution_insights SET subtest_id = v_target_sub_id WHERE subtest_id = v_source_sub.id;

        -- Delete source subtest (CASCADE deletes remaining norms)
        DELETE FROM official_norms WHERE subtest_id = v_source_sub.id;
        DELETE FROM official_subtests WHERE id = v_source_sub.id;
      ELSE
        -- No match: move subtest to target
        UPDATE official_subtests SET test_id = p_target_id WHERE id = v_source_sub.id;
        v_moved_subtests := v_moved_subtests + 1;
      END IF;
    END LOOP;

    -- Remap sessions
    WITH updated AS (
      UPDATE sessions SET test_id = p_target_id, test_name = v_target_name
      WHERE test_id = v_source_id
      RETURNING id
    )
    SELECT count(*) INTO v_row_cnt FROM updated;
    v_updated_sessions := v_updated_sessions + v_row_cnt;

    -- Remap contribution_insights test-level
    UPDATE contribution_insights SET test_id = p_target_id WHERE test_id = v_source_id;

    -- Delete source test
    DELETE FROM official_tests WHERE id = v_source_id;
    v_merged_tests := v_merged_tests + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'merged_tests', v_merged_tests,
    'moved_subtests', v_moved_subtests,
    'migrated_norms', v_migrated_norms,
    'updated_sessions', v_updated_sessions,
    'target_name', v_target_name
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_promote_subtests(p_subtest_ids text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_promoted int := 0;
  v_sub_id text;
BEGIN
  IF NOT check_is_admin() THEN
    RAISE EXCEPTION 'Unauthorized' USING ERRCODE = '42501';
  END IF;

  FOREACH v_sub_id IN ARRAY p_subtest_ids
  LOOP
    UPDATE official_subtests SET organization_id = NULL WHERE id = v_sub_id AND organization_id IS NOT NULL;
    IF FOUND THEN
      UPDATE official_norms SET organization_id = NULL WHERE subtest_id = v_sub_id AND organization_id IS NOT NULL;
      v_promoted := v_promoted + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('promoted', v_promoted);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_promote_test(p_test_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_private_test record;
  v_public_test record;
  v_private_sub record;
  v_target_sub_id text;
  v_new_subtests integer := 0;
  v_merged_norms integer := 0;
  v_rows integer := 0;
BEGIN
  IF NOT check_is_admin() THEN
    RAISE EXCEPTION 'not authorized' USING ERRCODE = '42501';
  END IF;

  SELECT id, name INTO v_private_test
  FROM official_tests
  WHERE id = p_test_id;

  IF v_private_test IS NULL THEN
    RAISE EXCEPTION 'Test introuvable';
  END IF;

  SELECT id, name INTO v_public_test
  FROM official_tests
  WHERE organization_id IS NULL
    AND norm_name(name) = norm_name(v_private_test.name)
  LIMIT 1;

  IF v_public_test IS NULL THEN
    UPDATE official_norms
    SET organization_id = NULL
    WHERE subtest_id IN (SELECT id FROM official_subtests WHERE test_id = p_test_id);

    UPDATE official_subtests
    SET organization_id = NULL
    WHERE test_id = p_test_id;

    UPDATE official_tests
    SET organization_id = NULL
    WHERE id = p_test_id;

    RETURN jsonb_build_object('merged', false, 'target_name', v_private_test.name);
  END IF;

  FOR v_private_sub IN
    SELECT id, name FROM official_subtests WHERE test_id = p_test_id
  LOOP
    SELECT id INTO v_target_sub_id
    FROM official_subtests
    WHERE test_id = v_public_test.id
      AND norm_subtest_name(name) = norm_subtest_name(v_private_sub.name)
    LIMIT 1;

    IF v_target_sub_id IS NULL THEN
      UPDATE official_subtests
      SET test_id = v_public_test.id,
          organization_id = NULL
      WHERE id = v_private_sub.id;

      UPDATE official_norms
      SET organization_id = NULL
      WHERE subtest_id = v_private_sub.id;

      v_new_subtests := v_new_subtests + 1;
    ELSE
      INSERT INTO official_norms (
        subtest_id,
        organization_id,
        age_min_months,
        age_max_months,
        gender,
        raw_min,
        raw_max,
        mean,
        sd,
        standard_score,
        percentile
      )
      SELECT
        v_target_sub_id,
        NULL,
        n.age_min_months,
        n.age_max_months,
        n.gender,
        n.raw_min,
        n.raw_max,
        n.mean,
        n.sd,
        n.standard_score,
        n.percentile
      FROM official_norms n
      WHERE n.subtest_id = v_private_sub.id
        AND NOT EXISTS (
          SELECT 1 FROM official_norms e
          WHERE e.subtest_id = v_target_sub_id
            AND e.age_min_months IS NOT DISTINCT FROM n.age_min_months
            AND e.age_max_months IS NOT DISTINCT FROM n.age_max_months
            AND e.gender IS NOT DISTINCT FROM n.gender
            AND e.raw_min IS NOT DISTINCT FROM n.raw_min
            AND e.raw_max IS NOT DISTINCT FROM n.raw_max
            AND e.mean IS NOT DISTINCT FROM n.mean
            AND e.sd IS NOT DISTINCT FROM n.sd
            AND e.standard_score IS NOT DISTINCT FROM n.standard_score
            AND e.percentile IS NOT DISTINCT FROM n.percentile
        );

      GET DIAGNOSTICS v_rows = ROW_COUNT;
      v_merged_norms := v_merged_norms + v_rows;

      DELETE FROM official_norms WHERE subtest_id = v_private_sub.id;
      DELETE FROM official_subtests WHERE id = v_private_sub.id;
    END IF;
  END LOOP;

  DELETE FROM official_tests WHERE id = p_test_id;

  RETURN jsonb_build_object(
    'merged', true,
    'target_name', v_public_test.name,
    'new_subtests', v_new_subtests,
    'merged_norms', v_merged_norms
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.attach_subtests_to_test(p_test_id text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org_id uuid;
  v_sub jsonb;
  v_norm_row jsonb;
  v_sub_name text;
  v_sub_id text;
  v_existing_sub_id text;
  v_new_subtests int := 0;
  v_new_norms int := 0;
  v_test_exists boolean;
BEGIN
  -- Get caller's organization
  SELECT om.organization_id INTO v_org_id
  FROM organization_members om
  WHERE om.user_id = auth.uid()
  LIMIT 1;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'No organization found for user' USING ERRCODE = '42501';
  END IF;

  -- Verify the target test exists and is visible
  SELECT EXISTS(
    SELECT 1 FROM official_tests t 
    WHERE t.id = p_test_id 
      AND (t.organization_id IS NULL OR t.organization_id = v_org_id)
  ) INTO v_test_exists;

  IF NOT v_test_exists THEN
    RAISE EXCEPTION 'Test not found or not accessible' USING ERRCODE = '42704';
  END IF;

  -- Process each subtest in the payload
  FOR v_sub IN SELECT * FROM jsonb_array_elements(p_payload -> 'subtests')
  LOOP
    v_sub_name := v_sub ->> 'name';

    -- Check if this org already has a subtest with this normalized name under this test
    SELECT s.id INTO v_existing_sub_id
    FROM official_subtests s
    WHERE s.test_id = p_test_id
      AND s.organization_id = v_org_id
      AND norm_subtest_name(s.name) = norm_subtest_name(v_sub_name);

    -- Also check if there's a public subtest with this name (user adds norms to it via their org)
    IF v_existing_sub_id IS NULL THEN
      SELECT s.id INTO v_existing_sub_id
      FROM official_subtests s
      WHERE s.test_id = p_test_id
        AND s.organization_id IS NULL
        AND norm_subtest_name(s.name) = norm_subtest_name(v_sub_name);

      -- If public subtest exists, create a private copy for this org's norms
      IF v_existing_sub_id IS NOT NULL THEN
        v_sub_id := p_test_id || '_' || left(regexp_replace(lower(public.unaccent(trim(v_sub_name))), '[^a-z0-9]+', '_', 'g'), 50) || '_' || left(v_org_id::text, 8);
        INSERT INTO official_subtests (id, test_id, name, unit, score_type, computation_mode, organization_id)
        VALUES (
          v_sub_id,
          p_test_id,
          v_sub_name,
          COALESCE(v_sub ->> 'unit', 'pts'),
          COALESCE(v_sub ->> 'score_type', 'standard'),
          COALESCE(v_sub ->> 'computation_mode', 'PARAMETRIC'),
          v_org_id
        );
        v_new_subtests := v_new_subtests + 1;
        v_existing_sub_id := v_sub_id;
      END IF;
    END IF;

    IF v_existing_sub_id IS NULL THEN
      -- Create new private subtest
      v_sub_id := p_test_id || '_' || left(regexp_replace(lower(public.unaccent(trim(v_sub_name))), '[^a-z0-9]+', '_', 'g'), 50) || '_' || left(v_org_id::text, 8);
      INSERT INTO official_subtests (id, test_id, name, unit, score_type, computation_mode, organization_id)
      VALUES (
        v_sub_id,
        p_test_id,
        v_sub_name,
        COALESCE(v_sub ->> 'unit', 'pts'),
        COALESCE(v_sub ->> 'score_type', 'standard'),
        COALESCE(v_sub ->> 'computation_mode', 'PARAMETRIC'),
        v_org_id
      );
      v_new_subtests := v_new_subtests + 1;
      v_existing_sub_id := v_sub_id;
    END IF;

    -- Insert norms for this subtest (with org-level dedup)
    FOR v_norm_row IN SELECT * FROM jsonb_array_elements(v_sub -> 'norms')
    LOOP
      IF NOT EXISTS (
        SELECT 1 FROM official_norms n
        WHERE n.subtest_id = v_existing_sub_id
          AND n.age_min_months IS NOT DISTINCT FROM (v_norm_row ->> 'age_min_months')::int
          AND n.age_max_months IS NOT DISTINCT FROM (v_norm_row ->> 'age_max_months')::int
          AND n.gender IS NOT DISTINCT FROM (v_norm_row ->> 'gender')
          AND n.raw_min IS NOT DISTINCT FROM (v_norm_row ->> 'raw_min')::real
          AND n.raw_max IS NOT DISTINCT FROM (v_norm_row ->> 'raw_max')::real
          AND n.mean IS NOT DISTINCT FROM (v_norm_row ->> 'mean')::real
          AND n.sd IS NOT DISTINCT FROM (v_norm_row ->> 'sd')::real
          AND n.standard_score IS NOT DISTINCT FROM (v_norm_row ->> 'standard_score')::real
          AND n.percentile IS NOT DISTINCT FROM (v_norm_row ->> 'percentile')::real
      ) THEN
        INSERT INTO official_norms (subtest_id, organization_id, age_min_months, age_max_months, gender, raw_min, raw_max, mean, sd, standard_score, percentile)
        VALUES (
          v_existing_sub_id,
          v_org_id,
          (v_norm_row ->> 'age_min_months')::int,
          (v_norm_row ->> 'age_max_months')::int,
          COALESCE(v_norm_row ->> 'gender', 'Mixed'),
          (v_norm_row ->> 'raw_min')::real,
          (v_norm_row ->> 'raw_max')::real,
          (v_norm_row ->> 'mean')::real,
          (v_norm_row ->> 'sd')::real,
          (v_norm_row ->> 'standard_score')::real,
          (v_norm_row ->> 'percentile')::real
        );
        v_new_norms := v_new_norms + 1;
      END IF;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object(
    'new_subtests', v_new_subtests,
    'new_norms', v_new_norms,
    'test_id', p_test_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.bootstrap_org_for_user(p_user_id uuid, p_org_name text DEFAULT 'Mon Cabinet'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_org_id uuid;
    v_has_sub boolean;
BEGIN
    -- Guard: caller must be the same user
    IF auth.uid() IS DISTINCT FROM p_user_id THEN
        RAISE EXCEPTION 'Forbidden: you can only bootstrap your own organisation';
    END IF;

    -- 1. Organisation + Membership
    SELECT organization_id INTO v_org_id
    FROM organization_members
    WHERE user_id = p_user_id
    LIMIT 1;

    IF v_org_id IS NULL THEN
        INSERT INTO organizations (name)
        VALUES (p_org_name)
        RETURNING id INTO v_org_id;

        INSERT INTO organization_members (organization_id, user_id, role)
        VALUES (v_org_id, p_user_id, 'owner');
    END IF;

    -- 2. Subscription (trial 14 days if missing)
    SELECT EXISTS(
        SELECT 1 FROM subscriptions WHERE user_id = p_user_id
    ) INTO v_has_sub;

    IF NOT v_has_sub THEN
        INSERT INTO subscriptions (user_id, plan_id, status, trial_ends_at)
        VALUES (
            p_user_id,
            'free',
            'trialing',
            now() + interval '14 days'
        );
    END IF;

    RETURN v_org_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.bootstrap_practitioner_for_user(p_user_id uuid, p_email text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    -- Guard: caller must be the same user
    IF auth.uid() IS DISTINCT FROM p_user_id THEN
        RAISE EXCEPTION 'Forbidden: you can only bootstrap your own profile';
    END IF;

    IF p_email IS NULL OR length(p_email) = 0 THEN
        RAISE EXCEPTION 'Missing email';
    END IF;

    IF EXISTS (SELECT 1 FROM practitioners WHERE id = p_user_id) THEN
        RETURN true;
    END IF;

    INSERT INTO practitioners (id, email, encryption_salt, encryption_validator)
    VALUES (p_user_id, p_email, 'pending', 'pending');

    RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_paid_access()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  sub record;
BEGIN
  SELECT * INTO sub FROM public.subscriptions WHERE user_id = auth.uid();

  -- Si pas d'abonnement trouvé, bloquer par sécurité
  IF sub IS NULL THEN
    RETURN FALSE;
  END IF;

  -- CAS 1 : Abonnement Payant Actif ('essential', 'performance', 'expert')
  -- Note: On accepte 'expert' comme payant, mais il consommera des crédits via consume_credit
  IF sub.plan_id != 'free' AND sub.status = 'active' THEN
    RETURN TRUE;
  END IF;

  -- CAS 2 : Essai Gratuit (Free Trial)
  -- Autorisé SEULEMENT si la date d'essai n'est pas expirée
  IF sub.plan_id = 'free' AND (sub.trial_ends_at > now()) THEN
    RETURN TRUE;
  END IF;

  -- Sinon (Essai expiré ou abonnement annulé) -> BLOQUÉ
  RETURN FALSE;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_rate_limit(p_max_per_hour integer DEFAULT 10)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET row_security TO 'off'
AS $function$
DECLARE
  v_count integer;
BEGIN
  SELECT count(*) INTO v_count
  FROM public.ai_request_log
  WHERE user_id = auth.uid()
    AND created_at > now() - interval '1 hour';

  IF v_count >= p_max_per_hour THEN
    RETURN false;
  END IF;

  INSERT INTO public.ai_request_log (user_id)
  VALUES (auth.uid());

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_signup_rate_limit(p_ip_hash text, p_email_hash text DEFAULT NULL::text, p_max_per_hour integer DEFAULT 5)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET row_security TO 'off'
AS $function$
DECLARE
  v_count integer;
BEGIN
  IF p_ip_hash IS NULL OR length(p_ip_hash) < 8 THEN
    RETURN false;
  END IF;

  SELECT count(*) INTO v_count
  FROM public.signup_rate_limit_log
  WHERE ip_hash = p_ip_hash
    AND created_at > now() - interval '1 hour';

  IF v_count >= p_max_per_hour THEN
    RETURN false;
  END IF;

  INSERT INTO public.signup_rate_limit_log (ip_hash, email_hash)
  VALUES (p_ip_hash, p_email_hash);

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.compute_score(p_subtest_id text, p_raw_score real, p_age_months integer, p_gender text DEFAULT 'Mixed'::text, p_class_level text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_subtest       record;
  v_norm          record;
  v_lookup        record;
  v_z             real;
  v_standard      real;
  v_percentile    real;
BEGIN
  -- 1. Récupérer la définition du sous-test
  SELECT * INTO v_subtest
  FROM public.official_subtests
  WHERE id = p_subtest_id
  LIMIT 1;

  IF v_subtest IS NULL THEN
    RETURN NULL;
  END IF;

  -- 2. Chercher la norme applicable (priorité genre spécifique > Mixed)
  SELECT * INTO v_norm
  FROM public.official_norms
  WHERE subtest_id = p_subtest_id
    AND age_min_months <= p_age_months
    AND age_max_months >= p_age_months
    AND (gender = p_gender OR gender = 'Mixed')
  ORDER BY 
    CASE WHEN gender = p_gender THEN 0 ELSE 1 END  -- Priorité genre spécifique
  LIMIT 1;

  IF v_norm IS NULL THEN
    RETURN NULL;
  END IF;

  -- 3. BRANCHE A : MODE PARAMÉTRIQUE
  IF v_norm.mean IS NOT NULL AND v_norm.sd IS NOT NULL AND v_norm.sd > 0 THEN
    v_z := (p_raw_score - v_norm.mean) / v_norm.sd;

    -- Conversion selon score_type du sous-test
    IF v_subtest.score_type = 'standard' THEN
      v_standard := 100 + (v_z * 15);
      v_percentile := (0.5 * (1.0 + erf(v_z / sqrt(2.0)))) * 100;
    ELSIF v_subtest.score_type = 'scaled' THEN
      v_standard := 10 + (v_z * 3);
      v_percentile := (0.5 * (1.0 + erf(v_z / sqrt(2.0)))) * 100;
    ELSIF v_subtest.score_type = 'sten' THEN
      v_standard := 5.5 + (v_z * 2);
      v_percentile := (0.5 * (1.0 + erf(v_z / sqrt(2.0)))) * 100;
    ELSIF v_subtest.score_type = 't_score' THEN
      v_standard := 50 + (v_z * 10);
      v_percentile := (0.5 * (1.0 + erf(v_z / sqrt(2.0)))) * 100;
    ELSE
      -- Défaut: note standard (100/15)
      v_standard := 100 + (v_z * 15);
      v_percentile := (0.5 * (1.0 + erf(v_z / sqrt(2.0)))) * 100;
    END IF;

    RETURN jsonb_build_object(
      'raw', p_raw_score,
      'standard', round(v_standard::numeric, 1),
      'percentile', round(v_percentile::numeric, 1),
      'zScore', round(v_z::numeric, 2),
      'method', 'PARAMETRIC'
    );
  END IF;

  -- 4. BRANCHE B : MODE LOOKUP
  SELECT * INTO v_lookup
  FROM public.official_norms
  WHERE subtest_id = p_subtest_id
    AND age_min_months <= p_age_months
    AND age_max_months >= p_age_months
    AND raw_min <= p_raw_score
    AND raw_max >= p_raw_score
    AND (gender = p_gender OR gender = 'Mixed')
  ORDER BY 
    CASE WHEN gender = p_gender THEN 0 ELSE 1 END
  LIMIT 1;

  IF v_lookup IS NOT NULL THEN
    RETURN jsonb_build_object(
      'raw', p_raw_score,
      'standard', COALESCE(v_lookup.standard_score, 0),
      'percentile', COALESCE(v_lookup.percentile, 0),
      'zScore', 0,
      'method', 'LOOKUP'
    );
  END IF;

  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.consume_credit()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_credits      integer;
  v_is_admin     boolean;
  v_plan_id      text;
  v_status       text;
  v_gen_id       uuid;
BEGIN
  -- 1. Récupérer infos praticien
  SELECT credits, is_admin INTO v_credits, v_is_admin
  FROM public.practitioners 
  WHERE id = auth.uid();

  -- 2. Récupérer abonnement
  SELECT plan_id, status INTO v_plan_id, v_status
  FROM public.subscriptions
  WHERE user_id = auth.uid();

  -- CAS 1 : Admin → illimité (log quand même)
  IF v_is_admin = true THEN
    INSERT INTO public.generation_log (user_id, status)
    VALUES (auth.uid(), 'consumed')
    RETURNING id INTO v_gen_id;
    RETURN v_gen_id;
  END IF;

  -- CAS 2 : Plan Expert actif → illimité
  IF v_plan_id = 'expert' AND v_status = 'active' THEN
    INSERT INTO public.generation_log (user_id, status)
    VALUES (auth.uid(), 'consumed')
    RETURNING id INTO v_gen_id;
    RETURN v_gen_id;
  END IF;

  -- CAS 3 : Vérifier accès payant ou trial valide
  IF NOT public.check_paid_access() THEN
    RETURN NULL;
  END IF;

  -- CAS 4 : Crédits classiques
  IF v_credits > 0 THEN
    PERFORM set_config('app.internal_operation', 'true', true);

    UPDATE public.practitioners 
    SET credits = credits - 1 
    WHERE id = auth.uid();

    PERFORM set_config('app.internal_operation', 'false', true);

    INSERT INTO public.generation_log (user_id, status)
    VALUES (auth.uid(), 'consumed')
    RETURNING id INTO v_gen_id;

    RETURN v_gen_id;
  ELSE
    RETURN NULL;  -- Pas assez de crédits
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_private_test(p_payload jsonb)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org_id uuid;
  v_test jsonb;
  v_test_id text;
  v_test_name text;
  v_category_id text;
  v_version text;
  v_author text;
  v_sub jsonb;
  v_sub_name text;
  v_sub_id text;
  v_subtests jsonb;
  v_norms jsonb;
BEGIN
  SELECT organization_id INTO v_org_id
  FROM organization_members
  WHERE user_id = auth.uid()
  LIMIT 1;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'No organization found for user' USING ERRCODE = '42501';
  END IF;

  v_test := COALESCE(p_payload->'test', '{}'::jsonb);
  v_test_name := COALESCE(v_test->>'name', '');
  IF v_test_name = '' THEN
    RAISE EXCEPTION 'Test name missing';
  END IF;

  v_category_id := COALESCE(v_test->>'category_id', '');
  v_version := COALESCE(v_test->>'version', '1.0');
  v_author := COALESCE(
    v_test->>'author',
    COALESCE(current_setting('request.jwt.claims', true)::json->>'email', '')
  );

  v_test_id := concat('priv_', split_part(v_org_id::text, '-', 1), '_', substr(gen_random_uuid()::text, 1, 8));

  INSERT INTO official_tests (id, name, category_id, version, author, organization_id)
  VALUES (v_test_id, v_test_name, v_category_id, v_version, v_author, v_org_id);

  v_subtests := COALESCE(p_payload->'subtests', '[]'::jsonb);
  FOR v_sub IN SELECT * FROM jsonb_array_elements(v_subtests)
  LOOP
    v_sub_name := COALESCE(v_sub->>'name', '');
    IF v_sub_name = '' THEN
      RAISE EXCEPTION 'Subtest name missing';
    END IF;

    v_sub_id := concat(
      v_test_id,
      '_',
      substring(regexp_replace(lower(v_sub_name), '[^a-z0-9]+', '_', 'g') for 50)
    );

    INSERT INTO official_subtests (
      id,
      test_id,
      name,
      unit,
      score_type,
      computation_mode
    )
    VALUES (
      v_sub_id,
      v_test_id,
      v_sub_name,
      COALESCE(v_sub->>'unit', 'pts'),
      COALESCE(v_sub->>'score_type', 'standard'),
      COALESCE(v_sub->>'computation_mode', 'LOOKUP')
    );

    v_norms := v_sub->'norms';
    IF v_norms IS NOT NULL AND jsonb_array_length(v_norms) > 0 THEN
      INSERT INTO official_norms (
        subtest_id,
        organization_id,
        age_min_months,
        age_max_months,
        gender,
        raw_min,
        raw_max,
        mean,
        sd,
        standard_score,
        percentile
      )
      SELECT
        v_sub_id,
        v_org_id,
        NULLIF(n->>'age_min_months', '')::integer,
        NULLIF(n->>'age_max_months', '')::integer,
        COALESCE(n->>'gender', 'Mixed'),
        NULLIF(n->>'raw_min', '')::real,
        NULLIF(n->>'raw_max', '')::real,
        NULLIF(n->>'mean', '')::real,
        NULLIF(n->>'sd', '')::real,
        NULLIF(n->>'standard_score', '')::real,
        NULLIF(n->>'percentile', '')::real
      FROM jsonb_array_elements(v_norms) AS n;
    END IF;
  END LOOP;

  RETURN v_test_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_practitioner_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF (TG_OP = 'INSERT') THEN
        NEW.credits := 3; 
        NEW.is_admin := false; 
    ELSIF (TG_OP = 'UPDATE') THEN
        -- Autoriser les RPC internes (consume_credit, refund_credit)
        IF current_setting('app.internal_operation', true) = 'true' THEN
            RETURN NEW;
        END IF;
        -- Bloquer les modifications directes par les users authentifiés
        IF auth.role() = 'authenticated' THEN
            IF NEW.credits <> OLD.credits THEN
                NEW.credits := OLD.credits;
            END IF;
            IF NEW.is_admin <> OLD.is_admin THEN
                NEW.is_admin := OLD.is_admin;
            END IF;
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_subscription_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    NEW.plan_id := 'free';
    NEW.status := 'trialing';
    NEW.trial_ends_at := (NOW() + INTERVAL '30 days');
    NEW.current_period_end := (NOW() + INTERVAL '30 days');
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.merge_private_test(p_target_id text, p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org_id uuid;
  v_sub jsonb;
  v_norm_row jsonb;
  v_sub_name text;
  v_existing_sub_id text;
  v_new_sub_id text;
  v_new_subtests int := 0;
  v_new_norms int := 0;
BEGIN
  -- Get caller's org
  SELECT om.organization_id INTO v_org_id
  FROM organization_members om
  WHERE om.user_id = auth.uid()
  LIMIT 1;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'No organization found' USING ERRCODE = '42501';
  END IF;

  -- Verify ownership of target test
  IF NOT EXISTS (
    SELECT 1 FROM official_tests 
    WHERE id = p_target_id AND organization_id = v_org_id
  ) THEN
    RAISE EXCEPTION 'Target test not owned by your organization' USING ERRCODE = '42501';
  END IF;

  FOR v_sub IN SELECT * FROM jsonb_array_elements(p_payload -> 'subtests')
  LOOP
    v_sub_name := v_sub ->> 'name';

    -- Use norm_subtest_name for matching (was norm_name before — BUG FIX)
    SELECT s.id INTO v_existing_sub_id
    FROM official_subtests s
    WHERE s.test_id = p_target_id
      AND norm_subtest_name(s.name) = norm_subtest_name(v_sub_name);

    IF v_existing_sub_id IS NULL THEN
      -- Create new subtest
      v_new_sub_id := p_target_id || '_' || left(regexp_replace(lower(public.unaccent(trim(v_sub_name))), '[^a-z0-9]+', '_', 'g'), 50);

      INSERT INTO official_subtests (id, test_id, name, unit, score_type, computation_mode, organization_id)
      VALUES (
        v_new_sub_id,
        p_target_id,
        v_sub_name,
        COALESCE(v_sub ->> 'unit', 'pts'),
        COALESCE(v_sub ->> 'score_type', 'standard'),
        COALESCE(v_sub ->> 'computation_mode', 'PARAMETRIC'),
        v_org_id
      );
      v_new_subtests := v_new_subtests + 1;
      v_existing_sub_id := v_new_sub_id;
    END IF;

    -- Insert norms with full 9-field dedup
    FOR v_norm_row IN SELECT * FROM jsonb_array_elements(v_sub -> 'norms')
    LOOP
      IF NOT EXISTS (
        SELECT 1 FROM official_norms n
        WHERE n.subtest_id = v_existing_sub_id
          AND n.age_min_months IS NOT DISTINCT FROM (v_norm_row ->> 'age_min_months')::int
          AND n.age_max_months IS NOT DISTINCT FROM (v_norm_row ->> 'age_max_months')::int
          AND n.gender IS NOT DISTINCT FROM (v_norm_row ->> 'gender')
          AND n.raw_min IS NOT DISTINCT FROM (v_norm_row ->> 'raw_min')::real
          AND n.raw_max IS NOT DISTINCT FROM (v_norm_row ->> 'raw_max')::real
          AND n.mean IS NOT DISTINCT FROM (v_norm_row ->> 'mean')::real
          AND n.sd IS NOT DISTINCT FROM (v_norm_row ->> 'sd')::real
          AND n.standard_score IS NOT DISTINCT FROM (v_norm_row ->> 'standard_score')::real
          AND n.percentile IS NOT DISTINCT FROM (v_norm_row ->> 'percentile')::real
      ) THEN
        INSERT INTO official_norms (subtest_id, organization_id, age_min_months, age_max_months, gender, raw_min, raw_max, mean, sd, standard_score, percentile)
        VALUES (
          v_existing_sub_id,
          v_org_id,
          (v_norm_row ->> 'age_min_months')::int,
          (v_norm_row ->> 'age_max_months')::int,
          COALESCE(v_norm_row ->> 'gender', 'Mixed'),
          (v_norm_row ->> 'raw_min')::real,
          (v_norm_row ->> 'raw_max')::real,
          (v_norm_row ->> 'mean')::real,
          (v_norm_row ->> 'sd')::real,
          (v_norm_row ->> 'standard_score')::real,
          (v_norm_row ->> 'percentile')::real
        );
        v_new_norms := v_new_norms + 1;
      END IF;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('new_subtests', v_new_subtests, 'new_norms', v_new_norms);
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_practitioner_sensitive_data()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$BEGIN
    -- Bypass pour service_role et opérations internes (RPC)
    IF (session_user = 'postgres' OR auth.role() = 'service_role') THEN
        RETURN NEW;
    END IF;

    IF current_setting('app.internal_operation', true) = 'true' THEN
        RETURN NEW;
    END IF;

    IF (NEW.credits IS DISTINCT FROM OLD.credits) THEN
        RAISE EXCEPTION 'SECURITY_VIOLATION: Vous ne pouvez pas modifier vos crédits manuellement.';
    END IF;

    IF (NEW.is_admin IS DISTINCT FROM OLD.is_admin) THEN
        RAISE EXCEPTION 'SECURITY_VIOLATION: Tentative de modification de privilèges bloquée.';
    END IF;

    IF (OLD.encryption_validator IS NOT NULL AND OLD.encryption_validator != 'pending') AND 
       (NEW.encryption_validator IS DISTINCT FROM OLD.encryption_validator) THEN
        RAISE EXCEPTION 'SECURITY_VIOLATION: Impossible de modifier les clés de chiffrement existantes.';
    END IF;

    RETURN NEW;
END;$function$

CREATE OR REPLACE FUNCTION public.purge_signup_rate_limit_log(p_retention_hours integer DEFAULT 24)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET row_security TO 'off'
AS $function$
DECLARE
  v_deleted integer;
BEGIN
  DELETE FROM public.signup_rate_limit_log
  WHERE created_at < now() - make_interval(hours => p_retention_hours);

  GET DIAGNOSTICS v_deleted = ROW_COUNT;
  RETURN v_deleted;
END;
$function$

CREATE OR REPLACE FUNCTION public.refund_credit(p_generation_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_log    record;
  v_plan   text;
  v_status text;
BEGIN
  -- 1. Vérifier que le log existe, appartient au user, et est en statut 'consumed'
  SELECT * INTO v_log
  FROM public.generation_log
  WHERE id = p_generation_id
    AND user_id = auth.uid()
    AND status = 'consumed';

  IF v_log IS NULL THEN
    RETURN FALSE;  -- Log invalide, déjà remboursé, ou pas le bon user
  END IF;

  -- 2. Vérifier que le log date de moins de 5 minutes (protection anti-abus)
  IF v_log.created_at < now() - interval '5 minutes' THEN
    RETURN FALSE;
  END IF;

  -- 3. Marquer comme remboursé
  UPDATE public.generation_log
  SET status = 'refunded', refunded_at = now()
  WHERE id = p_generation_id;

  -- 4. Ne rembourser le crédit que pour les plans non-illimités
  SELECT plan_id, status INTO v_plan, v_status
  FROM public.subscriptions
  WHERE user_id = auth.uid();

  IF (v_plan = 'expert' AND v_status = 'active') THEN
    RETURN TRUE;  -- Expert n'a pas perdu de crédit → rien à rembourser
  END IF;

  -- Vérifier admin
  IF (SELECT is_admin FROM practitioners WHERE id = auth.uid()) = true THEN
    RETURN TRUE;  -- Admin non plus
  END IF;

  -- 5. Rembourser effectivement le crédit
  PERFORM set_config('app.internal_operation', 'true', true);

  UPDATE public.practitioners
  SET credits = credits + 1
  WHERE id = auth.uid();

  PERFORM set_config('app.internal_operation', 'false', true);

  RETURN TRUE;
END;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$
